def count_k_palindromic_numbers(n: int, k: int) -> int:
    """ Count the number of good integers containing exactly n digits.

    An integer x is called k-palindromic if:
    - x is a palindrome (reads the same forwards and backwards)
    - x is divisible by k

    An integer is called good if its digits can be rearranged to form a k-palindromic integer.

    Note: Integers must not have leading zeros, neither before nor after rearrangement.

    Args:
        n: The number of digits (1 <= n <= 10)
        k: The divisor for k-palindromic property (1 <= k <= 9)

    Returns:
        The count of good integers with exactly n digits

    >>> count_k_palindromic_numbers(3, 5)
    27
    >>> count_k_palindromic_numbers(1, 4)
    2
    >>> count_k_palindromic_numbers(5, 6)
    2468
    """
    from math import factorial
    from itertools import product

    def can_form_palindrome(counts, n):
        """Check if multiset can form a palindrome"""
        odd_count = sum(1 for c in counts if c % 2 == 1)
        if n % 2 == 0:
            return odd_count == 0
        else:
            return odd_count == 1

    def get_left_half_multiset(counts, n):
        """Get the multiset for the first ceil(n/2) positions"""
        half_len = (n + 1) // 2
        left_counts = [0] * 10

        if n % 2 == 0:
            for d in range(10):
                left_counts[d] = counts[d] // 2
        else:
            odd_digit = -1
            for d in range(10):
                if counts[d] % 2 == 1:
                    odd_digit = d
                    break
            for d in range(10):
                if d == odd_digit:
                    left_counts[d] = counts[d] // 2 + 1
                else:
                    left_counts[d] = counts[d] // 2
        return left_counts

    def generate_distinct_permutations(counts, length, prefix=None):
        """Generate all distinct permutations of a multiset with given counts"""
        if prefix is None:
            prefix = []
        if length == 0:
            yield prefix[:]
            return
        for d in range(10):
            if counts[d] > 0:
                counts[d] -= 1
                prefix.append(d)
                yield from generate_distinct_permutations(counts, length - 1, prefix)
                prefix.pop()
                counts[d] += 1

    def build_palindrome(left_digits, n):
        """Build full palindrome from left half digits"""
        if n % 2 == 0:
            return left_digits + left_digits[::-1]
        else:
            return left_digits + left_digits[-2::-1]

    def check_multiset_good(counts, n, k):
        """Check if multiset can form a k-palindromic number"""
        if not can_form_palindrome(counts, n):
            return False

        left_counts = get_left_half_multiset(counts, n)
        half_len = (n + 1) // 2

        left_counts_copy = left_counts[:]
        for left_digits in generate_distinct_permutations(left_counts_copy, half_len):
            if left_digits[0] == 0:
                continue
            palindrome_digits = build_palindrome(left_digits, n)
            num = 0
            for d in palindrome_digits:
                num = num * 10 + d
            if num % k == 0:
                return True
        return False

    def count_numbers_with_multiset(counts, n):
        """Count n-digit numbers (no leading zero) with exactly this digit multiset"""
        total = factorial(n)
        for c in counts:
            total //= factorial(c)

        if counts[0] > 0:
            sub_total = factorial(n - 1)
            sub_counts = counts[:]
            sub_counts[0] -= 1
            for c in sub_counts:
                sub_total //= factorial(c)
            total -= sub_total

        return total

    # Generate all possible digit count arrays with sum n
    def generate_all_multisets(n, idx=0, current=None):
        if current is None:
            current = [0] * 10
        if idx == 10:
            if sum(current) == n:
                yield current[:]
            return
        remaining = n - sum(current)
        for count in range(remaining + 1):
            current[idx] = count
            yield from generate_all_multisets(n, idx + 1, current)
            current[idx] = 0

    result = 0
    for counts in generate_all_multisets(n):
        if check_multiset_good(counts, n, k):
            result += count_numbers_with_multiset(counts, n)

    return result
