from typing import List
from itertools import combinations


def sum_of_powers(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    n = len(nums)

    if k <= 1 or k > n:
        return 0

    # Sort the array
    sorted_nums = sorted(nums)

    # If k == 2, compute efficiently
    if k == 2:
        total = 0
        for i in range(n):
            for j in range(i + 1, n):
                total = (total + sorted_nums[j] - sorted_nums[i]) % MOD
        return total

    total = 0
    for combo in combinations(sorted_nums, k):
        # Find minimum absolute difference between consecutive elements in sorted combo
        min_diff = combo[1] - combo[0]
        for i in range(2, k):
            diff = combo[i] - combo[i - 1]
            if diff < min_diff:
                min_diff = diff
            if min_diff == 0:
                break
        total = (total + min_diff) % MOD

    return total
