Looking at the problem, I need to count integers in `[start, finish]` that end with suffix `s` and have all digits ≤ `limit`.

**Key insight:** Any valid number has the form `d * 10^k + val_s` where `k = len(s)`. I need to:
1. Check if `s` itself has digits > `limit` (if so, return 0)
2. Find the range of valid `d` values
3. Count numbers `d` in that range where all digits are ≤ `limit` (digit DP)

```python
def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    # Check if s has any digit > limit
    for c in s:
        if int(c) > limit:
            return 0

    val_s = int(s)
    k = len(s)
    power = 10 ** k

    if finish < val_s:
        return 0

    # d must satisfy: start <= d * power + val_s <= finish
    if start <= val_s:
        d_min = 0
    else:
        d_min = (start - val_s + power - 1) // power

    d_max = (finish - val_s) // power

    if d_min > d_max:
        return 0

    def count_valid_up_to(n: int) -> int:
        if n < 0:
            return 0

        s_n = str(n)
        length = len(s_n)

        # Count all numbers with fewer than `length` digits (0 to 10^(length-1)-1)
        count = 1  # for 0
        for d in range(1, length):
            count += limit * (limit + 1) ** (d - 1)

        digits = [int(c) for c in s_n]
        tight = True
        result = 0

        for i in range(length):
            current_digit = digits[i]
            upper = min(current_digit, limit) if tight else limit

            if upper > 0:
                num_choices = upper
                remaining_positions = length - i - 1
                result += num_choices * (limit + 1) ** remaining_positions

            if not tight:
                pass
            elif current_digit <= limit:
                tight = True
            else:
                tight = False

        if all(d <= limit for d in digits):
            result += 1

        return count + result

    return count_valid_up_to(d_max) - count_valid_up_to(d_min - 1)
